{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes internal HTTPS traffic to Dify."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"ack","product":"ack","label":"ACK cluster","group":"vpc","zones":["a","b"],"why":"Runs Dify and application workloads."}
{"t":"edge","id":"e-alb-ack","from":"alb","to":"ack"}
{"t":"node","id":"dify","product":"dify-on-ack","label":"Dify on ACK","group":"vpc","attachTo":"ack","why":"Low-code RAG builder hosting the chatbot UI and workflow."}
{"t":"node","id":"model","product":"model-studio","label":"Model Studio","group":"sg","why":"Qwen models for embedding and answer generation."}
{"t":"edge","id":"e-dify-model","from":"ack","to":"model","label":"API"}
{"t":"node","id":"vector","product":"milvus","label":"Milvus","group":"vpc","zones":["a","b"],"why":"Vector store for policy and wiki embeddings."}
{"t":"edge","id":"e-dify-vector","from":"ack","to":"vector","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"Document bucket","group":"sg","why":"Stores uploaded policy PDFs and wiki exports."}
{"t":"edge","id":"e-dify-docs","from":"ack","to":"docs","label":"read"}
{"t":"node","id":"db","product":"rds","label":"App database","group":"vpc","zones":["a","b"],"why":"Persists Dify metadata, conversations and configs."}
{"t":"edge","id":"e-dify-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Centralizes access and application logs."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"rec","product":"qwenwork","fit":"complement","why":"Ready-made workplace agent if you prefer no custom build."}
{"t":"done","summary":"Internal RAG assistant: employees reach Dify on ACK via ALB; Qwen models in Model Studio generate answers from Milvus vectors over OSS docs."}

{"t":"say","text":"I'll build a data platform in Singapore: RDS MySQL as the source, DTS for real-time replication to Hologres, MaxCompute for nightly batch, and Quick BI for dashboards."}
{"t":"plan","products":["rds","dts","hologres","maxcompute","dataworks","quick-bi","oss","sls"]}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"orders-db","product":"rds","label":"Orders MySQL","group":"vpc","zones":["a","b"],"why":"Source transactional database storing customer orders."}
{"t":"node","id":"dts-sync","product":"dts","label":"DTS Real-time Sync","group":"sg","why":"Streams CDC changes from RDS to Hologres with low latency."}
{"t":"edge","id":"e-orders-dts","from":"orders-db","to":"dts-sync","label":"CDC"}
{"t":"node","id":"hologres","product":"hologres","label":"Hologres Warehouse","group":"vpc","zones":["a","b"],"why":"Serves real-time analytics queries directly from replicated data."}
{"t":"edge","id":"e-dts-holo","from":"dts-sync","to":"hologres","label":"stream"}
{"t":"node","id":"maxcompute","product":"maxcompute","label":"MaxCompute Batch","group":"sg","why":"Runs heavy nightly batch SQL jobs over historical order data."}
{"t":"edge","id":"e-holo-maxcompute","from":"hologres","to":"maxcompute","label":"batch"}
{"t":"node","id":"dataworks","product":"dataworks","label":"DataWorks Scheduler","group":"sg","why":"Orchestrates nightly ETL pipelines between Hologres and MaxCompute."}
{"t":"edge","id":"e-dataworks-mc","from":"dataworks","to":"maxcompute","kind":"control","label":"schedule"}
{"t":"node","id":"oss-lake","product":"oss","label":"Data Lake OSS","group":"sg","why":"Stores raw exports and intermediate files for batch processing."}
{"t":"edge","id":"e-maxcompute-oss","from":"maxcompute","to":"oss-lake","label":"spill"}
{"t":"node","id":"quickbi","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Gives business users self-service reports over Hologres and MaxCompute."}
{"t":"edge","id":"e-quickbi-holo","from":"quickbi","to":"hologres","label":"query"}
{"t":"edge","id":"e-quickbi-mc","from":"quickbi","to":"maxcompute","label":"query"}
{"t":"node","id":"logs","product":"sls","label":"Pipeline Logs","group":"sg","why":"Centralizes logs and alerts for all data pipeline components."}
{"t":"edge","id":"e-dts-logs","from":"dts-sync","to":"logs","kind":"control"}
{"t":"edge","id":"e-dataworks-logs","from":"dataworks","to":"logs","kind":"control"}
{"t":"done","summary":"Real-time MySQL replication via DTS to Hologres, nightly batch on MaxCompute orchestrated by DataWorks, dashboards on Quick BI."}

{"t":"say","text":"I'll draw an IoT telemetry pipeline: devices to IoT Platform, MQTT broker, Flink for real-time anomaly detection, and a live dashboard."}
{"t":"plan","products":["iot-devices","iot-platform","mqtt","kafka","flink","tair","lindorm","datav","sls"]}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100K IoT devices","group":"field","why":"Sensors sending telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Telemetry VPC","parent":"sg"}
{"t":"node","id":"iot","product":"iot-platform","label":"IoT Platform","group":"sg","why":"Ingests and routes device telemetry via MQTT."}
{"t":"edge","id":"e-devices-iot","from":"devices","to":"iot","label":"MQTT"}
{"t":"node","id":"mq","product":"mqtt","label":"ApsaraMQ for MQTT","group":"sg","why":"High-throughput MQTT broker for 100K devices."}
{"t":"edge","id":"e-iot-mq","from":"iot","to":"mq","label":"forward"}
{"t":"node","id":"stream","product":"kafka","label":"ApsaraMQ for Kafka","group":"vpc","why":"Buffers telemetry for stream processing."}
{"t":"edge","id":"e-mq-stream","from":"mq","to":"stream","label":"data","kind":"async"}
{"t":"node","id":"flink","product":"flink","label":"Flink stream jobs","group":"vpc","why":"Detects anomalies in real time over telemetry."}
{"t":"edge","id":"e-stream-flink","from":"stream","to":"flink","label":"consume"}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"Holds latest metrics and alert state for dashboard."}
{"t":"edge","id":"e-flink-cache","from":"flink","to":"cache","label":"alerts"}
{"t":"node","id":"tsdb","product":"lindorm","label":"Lindorm time series","group":"vpc","why":"Stores historical telemetry for trend analysis."}
{"t":"edge","id":"e-flink-tsdb","from":"flink","to":"tsdb","label":"write"}
{"t":"node","id":"dash","product":"datav","label":"DataV dashboard","group":"sg","why":"Live large-screen visualization of device health."}
{"t":"edge","id":"e-cache-dash","from":"cache","to":"dash","label":"read"}
{"t":"edge","id":"e-tsdb-dash","from":"tsdb","to":"dash","label":"query"}
{"t":"node","id":"logs","product":"sls","label":"Simple Log Service","group":"sg","why":"Collects pipeline logs and triggers alert rules."}
