{"t":"say","text":"I'll draw a hybrid architecture connecting your Singapore on-premises data center to Alibaba Cloud via Express Connect, with migration tooling."}
{"t":"req","text":"Private link from on-premises Singapore to Alibaba Cloud"}
{"t":"req","text":"Step-by-step VM migration to cloud"}
{"t":"plan","products":["onprem-dc","express-connect","cen","vpc","ecs","smc","dts","nat","eip","cloudmonitor"]}
{"t":"group","id":"onprem","kind":"onprem","label":"On-premises DC (Singapore)","parent":null}
{"t":"node","id":"dc","product":"onprem-dc","label":"On-premises Data Center","group":"onprem","why":"Your existing data center in Singapore hosting VMs."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Cloud VPC","parent":"sg"}
{"t":"node","id":"express","product":"express-connect","label":"Express Connect","group":"vpc","why":"Dedicated private link between on-prem and cloud VPC."}
{"t":"edge","id":"e-dc-express","from":"dc","to":"express","label":"private link"}
{"t":"node","id":"cen","product":"cen","label":"CEN","group":null,"why":"Global network hub linking on-prem VBR and cloud VPC."}
{"t":"edge","id":"e-express-cen","from":"express","to":"cen","label":"VBR attach"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Outbound internet for migrated VMs during transition."}
{"t":"node","id":"eip","product":"eip","label":"EIP","group":"vpc","attachTo":"nat","why":"Public IP for NAT Gateway outbound access."}
{"t":"node","id":"app","product":"ecs","label":"Migrated ECS VMs","group":"vpc","zones":["a","b"],"why":"Target compute instances for step-by-step VM migration."}
{"t":"edge","id":"e-nat-app","from":"nat","to":"app","label":"SNAT"}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Agent-based incremental VM migration from on-prem to ECS."}
{"t":"edge","id":"e-dc-smc","from":"dc","to":"smc","label":"migrate VMs","kind":"data"}
{"t":"edge","id":"e-smc-app","from":"smc","to":"app","label":"deploy","kind":"control"}
{"t":"node","id":"dts","product":"dts","label":"DTS","group":"sg","why":"Syncs databases from on-prem to cloud during cutover."}
