{"t":"say","text":"I'll design a live-streaming and VOD platform for e-sports fans using ApsaraVideo Live, VOD, ESA for edge delivery, and OSS for storage."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","live","vod","oss","cdn","sls","rds","tair"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"E-sports fans","group":"internet","why":"Viewers watching live streams and VOD content."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves platform domain to ESA edge nodes."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates dynamic API calls and caches static assets globally."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Platform VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes HTTP traffic to backend services across two zones."}
