{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"node","id":"db","product":"rds","label":"Platform DB","group":"vpc","zones":["a","b"],"why":"Stores users, channels, schedules and billing data."}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects access logs, stream metrics and application traces."}
